N=38358837682
S=isqrt(N+1)+1
sieve=bytearray([1])*(S+1)
sieve[:2]=b'\0\0'
for j in range(2,isqrt(S)+1):
    if sieve[j]:
        sieve[j*j::j]=b'\0'*((S-j*j)//j+1)
pr=[j for j in range(S+1) if sieve[j]]
@lru_cache(None)
def phi(n,a):
    if a==0:return n
    if n<pr[a-1]:return 1
    if n<=S and pr[a-1]**2>n:return max(1,bisect_right(pr,n)-a+1)
    return phi(n,a-1)-phi(n//pr[a-1],a-1)

@lru_cache(None)
def pi(n):
    if n<=S:return bisect_right(pr,n)
    a=pi(isqrt(isqrt(n)))
    b=pi(isqrt(n))
    ans=phi(n,a)+a-1
    for i in range(a,b):
        y=n//pr[i]
        ans-=pi(y)-i
        for j in range(i,pi(isqrt(y))):
            ans-=pi(y//pr[j])-j
    return ans

def rr(t,j,up):
    # r0's prefix bounds 100000,100 are reused, but sharp integrals
    # after the pivot 16 give coefficients 8/7 and 8/3.
    p,b=AT[j],BT[j]+I('-.9999' if up else '1.4262')
    return p*(1+I(F(8,7))/t)+b*(1+I(F(8,3))/t)*exp(-t/2)+(100000*p+100*b+50)*t*exp(-t)

def which(t,z,up,b):
    # The optimal bound for a cell is chosen by comparing worst endpoints.
    terms=[rr(t,j,up) for j in range(len(TS))]
    if up and z.b<=I('43.749').a:
        terms.append(2*t*exp(-t)) # sign to 10^19, finite RH paper §3.3 p.5
    if b is not None:
        terms.append(rd(t,b))
    return min(terms,key=lambda z:z.b)

def check_ram_constants():
    for T,t in zip(TS,AT):
        less(PI/(T-1)+PI*PI/(3*T*T),t)
    less(exp(I('39.32')),120000000000000000)
    # Prefix integrals as upper Riemann sums in log coordinates.
    for h,n in [(I(1),100000),(I('.5'),100)]:
        f=(exp(h)-exp(h*LN2))/(h*LN2**2)
        f+=sum((exp(h*(k+1))-exp(h*k))/(h*k*k) for k in range(1,16))
        less(f,n)
    less(2/LN2+22/(LN2**2),50)

def plat(t,b=Q):
    y=I('186.09' if b==Q else '167.96')
    k=1-b
    z=I(max(0,(t-y).a),max(0,(t-y).b))
    return a*exp(-k*z)

def rd(t,b):
    # use plateau with log-ratio rate k; spectral density needed only at anchor
    return B*(1+I(F(8,3))/t)*exp(-t/2)+plat(t,b)*(1+I(F(7,5))/t)+(100000*a+100*B+3)*t*exp(-t)

def verify_common():
    anchor()
    for b,y in [(Q,I('186.09')),(J,I('167.96'))]:
        less(c(y,b)*exp(-(1-b)*y),a)
    t=I('36.5')
    less(2*P(t)+C/t**(N+1)+rr(t,2,True),'2.07')

