    return I('.022')*(1+I('1.16')/z)*exp(-z/8)+I('1.43')*(1+3/z)*exp(-z/2)+(I('7e-17')*exp(185-z)+3*exp(-z))*z

def rn(z):
    return I('.0045')*(z*z+8*z/7)*exp(-z/8)+I('1.43')*(1+3/z)*exp(-z/2)+(I('7e-17')*exp(185-z)+3*exp(-z))*z

def choose(vals):
    return min(vals,key=lambda x:x.b)
