            B t=log_int(10000), u=log_log(t);
            d[0].h=r0.h-u.l; d[1].h=r1.h-u.l; d[2].h=r2.h-t.l;
        }
        unsigned h=lo;
        while(h*h<q) ++h;
        assert(prod_up(d[0].h*h,Lq.h)<rat(170,100).l);
        assert(prod_up(d[1].h*h,Lq.h)<rat(170,100).l);
        assert(d[2].h*h<rat(188,100).l);

