        # Collapse to exact upward-rounded rationals, so weights are nonnegative.
        ds.append(min(d.b,ds[-1] if ds else d.b))
    return [(g[-1],I(ds[-1],ds[-1]))]+[(g[i],I(ds[i-1]-ds[i],ds[i-1]-ds[i])) for i in range(1,len(ds))]

